// Generated by AI, edited by humans
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { preview } from 'vite';
import { buildPages } from './build_pages.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const sseClients = new Set();

function notifyReload() {
    for (const res of sseClients) {
        try {
            res.write('event: reload\ndata: reload\n\n');
        } catch {
            sseClients.delete(res);
        }
    }
}

function runPythonBuild(isDev = false) {
    return new Promise((resolve, reject) => {
        const args = ['build_website.py'];
        if (isDev) {
            args.push('--dev');
        }

        const proc = spawn('python', args, {
            cwd: __dirname,
            stdio: 'inherit',
            shell: false,
        });

        proc.on('close', (code) => {
            if (code === 0) {
                resolve();
            } else {
                reject(new Error(`Python build failed with code ${code}`));
            }
        });
        proc.on('error', reject);
    });
}

async function main() {
    console.log('[dev] 1/2: Performing initial full build...');
    await buildPages({ emptyOutDir: true });
    await runPythonBuild(false);

    console.log('\n[dev] 2/2: Starting local preview server...');
    const port = process.env.PORT ? parseInt(process.env.PORT, 10) : 4173;

    const liveReloadPlugin = {
        name: 'dev-livereload',
        configurePreviewServer(server) {
            server.middlewares.use((req, res, next) => {
                if (typeof req.url !== 'string') {
                    throw new Error(`[dev] Expected req.url to be string, received ${typeof req.url}`);
                }
                const url = req.url.split('?')[0];

                if (url === '/__livereload') {
                    res.writeHead(200, {
                        'Content-Type': 'text/event-stream; charset=utf-8',
                        'Cache-Control': 'no-cache, no-transform',
                        'Connection': 'keep-alive',
                        'Access-Control-Allow-Origin': '*',
                    });
                    res.write(': connected\n\n');
                    sseClients.add(res);
                    req.on('close', () => sseClients.delete(res));
                    return;
                }

                // Check if this request corresponds to an HTML file in root/_website
                const cleanPath = url.replace(/^\/+/, '').replace(/\/+$/, '');
                const websiteRoot = path.join(__dirname, 'root', '_website');

                const candidateFiles = cleanPath === ''
                    ? [path.join(websiteRoot, 'index.html')]
                    : [
                        path.join(websiteRoot, cleanPath),
                        path.join(websiteRoot, `${cleanPath}.html`),
                        path.join(websiteRoot, cleanPath, 'index.html'),
                    ];

                for (const candidate of candidateFiles) {
                    if (candidate.endsWith('.html') && fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
                        let html = fs.readFileSync(candidate, 'utf-8');
                        const reloadScript = `
<script>
(() => {
    try {
        const es = new EventSource('/__livereload');
        const reload = () => {
            console.log('[dev] Reloading page...');
            location.reload();
        };
        es.onmessage = reload;
        es.addEventListener('reload', reload);
    } catch (e) {
        console.error('[dev] Live reload error:', e);
    }
})();
</script>`;
                        if (html.includes('</body>')) {
                            html = html.replace('</body>', `${reloadScript}\n</body>`);
                        } else {
                            html += reloadScript;
                        }

                        res.writeHead(200, {
                            'Content-Type': 'text/html; charset=utf-8',
                            'Cache-Control': 'no-cache, no-store, must-revalidate',
                            'Pragma': 'no-cache',
                            'Expires': '0',
                        });
                        res.end(html);
                        return;
                    }
                }

                next();
            });
        },
    };

    const server = await preview({
        plugins: [liveReloadPlugin],
        preview: {
            port,
        },
    });

    console.log(`\n  ➜  Local:   http://localhost:${port}/`);
    console.log('\n[dev] Watching for file changes (press Ctrl+C to stop)...');

    let isBuilding = false;
    let pendingRebuild = false;
    let debounceTimer = null;

    async function executeBuild() {
        isBuilding = true;
        try {
            console.log('\n[dev] Running fast Vite build...');
            await buildPages({ emptyOutDir: false });

            console.log('[dev] Updating website data (python build_website.py --dev)...');
            await runPythonBuild(true);

            console.log('[dev] Rebuild complete! Reloading browser...');
            notifyReload();
        } catch (err) {
            console.error('[dev] Rebuild error:', err.message);
        } finally {
            isBuilding = false;
            if (pendingRebuild) {
                pendingRebuild = false;
                scheduleRebuild();
            }
        }
    }

    function scheduleRebuild() {
        if (debounceTimer) clearTimeout(debounceTimer);
        debounceTimer = setTimeout(() => {
            if (isBuilding) {
                pendingRebuild = true;
                return;
            }
            executeBuild();
        }, 300);
    }

    const srcDir = path.join(__dirname, 'src');
    if (fs.existsSync(srcDir)) {
        fs.watch(srcDir, { recursive: true }, (_, fname) => {
            if (fname) scheduleRebuild();
        });
    }

    const pyFiles = ['build_website.py', 'statuspage_generator.py'];
    for (const pyFile of pyFiles) {
        const fullPath = path.join(__dirname, pyFile);
        if (fs.existsSync(fullPath)) {
            fs.watch(fullPath, () => scheduleRebuild());
        }
    }
}

main().catch((err) => {
    console.error('[dev] Startup error:', err);
    process.exit(1);
});
